var t=`0956-sukiyaki`;var n=`world-0956`;var s=`JP`;var a=`east-asia`;var r=4;var o=40;var u={en:`Sukiyaki`,ua:`Сукіякі`};var g={en:`Sukiyaki is a Japan dish made with light soy sauce, beef sirloin, tofu (firm), shiitake mushroom. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сукіякі, страва кухні країни Японія. Основні складники: світлий соєвий соус, яловичий сирлойн, твердий тофу, шиїтаке. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Cook the listed sauce ingredients over medium-low heat for about 9 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 9 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:9,i:[[`dashi-stock`,550,`ml`],[`light-soy-sauce`,95,`ml`],[`mirin`,85,`ml`],[`white-granulated-sugar`,45,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`beef-sirloin`,550,`g`],[`unsalted-butter`,35,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 11 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 11 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:11,i:[[`tofu-firm`,300,`g`],[`shiitake-mushroom`,250,`g`],[`napa-cabbage`,350,`g`],[`green-onion`,140,`g`]]},{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`udon-noodles`,240,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,25,`g`]]}];var m={slug:t,id:n,country:`JP`,region:a,servings:4,minutes:40,title:u,text:g,steps:d};export{s as country,m as default,n as id,o as minutes,a as region,r as servings,t as slug,d as steps,g as text,u as title};